/* animația umbrei: de la −4 h la +4 h față de maximul eclipsei alese */
function stopS() { if (sTimer) { cancelAnimationFrame(sTimer); sTimer = null; } $("ec-splay").textContent = $("ec-splay2").textContent = "▶ " + D.playS; }
